import{_ as n,o as i,c as s,l as a,t as r,a as t,N as e}from"./chunks/framework.CMqbtke2.js";const y=JSON.parse('{"title":"gitprotocol-v2 | x-cmd man (git man5) | Git Wire Protocol, Version 2","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitprotocol-v2 - Git Wire Protocol, Version 2","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitprotocol-v2 | x-cmd man (git man5) | Git Wire Protocol, Version 2"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitprotocol-v2 - Git Wire Protocol, Version 2"}]]},"headers":[],"params":{"isMan":true,"man":"gitprotocol-v2","category":"git man5","desc":"Git Wire Protocol, Version 2"},"relativePath":"git/man5/gitprotocol-v2.md","filePath":"git/man5/gitprotocol-v2.md"}'),l={name:"git/man5/gitprotocol-v2.md"},c={class:"visually-hidden"},d=e(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitprotocol-v2 - Git Wire Protocol, Version 2</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">over-the-wire-protocol</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This document presents a specification for a version 2 of Git&#39;s wire protocol. Protocol v2 will improve upon v1 in the following ways:</p><blockquote><p>·</p><p>Instead of multiple service names, multiple commands will be supported by a single service</p></blockquote><blockquote><p>·</p><p>Easily extendable as capabilities are moved into their own section of the protocol, no longer being hidden behind a NUL byte and limited by the size of a pkt-line</p></blockquote><blockquote><p>·</p><p>Separate out other information hidden behind NUL bytes (e.g. agent string as a capability and symrefs can be requested using <em>ls-refs</em>)</p></blockquote><blockquote><p>·</p><p>Reference advertisement will be omitted unless explicitly requested</p></blockquote><blockquote><p>·</p><p>ls-refs command to explicitly request some refs</p></blockquote><blockquote><p>·</p><p>Designed with http and stateless-rpc in mind. With clear flush semantics the http remote helper can simply act as a proxy</p></blockquote><p>In protocol v2 communication is command oriented. When first contacting a server a list of capabilities will advertised. Some of these capabilities will be commands which a client can request be executed. Once a command has completed, a client can reuse the connection and request that other commands be executed.</p><h2 id="packet-line-framing" tabindex="-1">PACKET-LINE FRAMING <a class="header-anchor" href="#packet-line-framing" aria-label="Permalink to &quot;PACKET-LINE FRAMING&quot;">​</a></h2><p>All communication is done using packet-line framing, just as in v1. See <strong>gitprotocol-pack</strong>(5) and <strong>gitprotocol-common</strong>(5) for more information.</p><p>In protocol v2 these special packets will have the following semantics:</p><blockquote><p>·</p><p><em>0000</em> Flush Packet (flush-pkt) - indicates the end of a message</p></blockquote><blockquote><p>·</p><p><em>0001</em> Delimiter Packet (delim-pkt) - separates sections of a message</p></blockquote><blockquote><p>·</p><p><em>0002</em> Response End Packet (response-end-pkt) - indicates the end of a response for stateless connections</p></blockquote><h2 id="initial-client-request" tabindex="-1">INITIAL CLIENT REQUEST <a class="header-anchor" href="#initial-client-request" aria-label="Permalink to &quot;INITIAL CLIENT REQUEST&quot;">​</a></h2><p>In general a client can request to speak protocol v2 by sending <strong>version=2</strong> through the respective side-channel for the transport being used which inevitably sets <strong>GIT_PROTOCOL</strong>. More information can be found in <strong>gitprotocol-pack</strong>(5) and <strong>gitprotocol-http</strong>(5), as well as the <strong>GIT_PROTOCOL</strong> definition in <strong>git.txt</strong>. In all cases the response from the server is the capability advertisement.</p><h3 id="git-transport" tabindex="-1">Git Transport <a class="header-anchor" href="#git-transport" aria-label="Permalink to &quot;Git Transport&quot;">​</a></h3><p>When using the git:// transport, you can request to use protocol v2 by sending &quot;version=2&quot; as an extra parameter:</p><blockquote><pre><code>003egit-upload-pack /project.git\\0host=myserver.com\\0\\0version=2\\0
</code></pre></blockquote><h3 id="ssh-and-file-transport" tabindex="-1">SSH and File Transport <a class="header-anchor" href="#ssh-and-file-transport" aria-label="Permalink to &quot;SSH and File Transport&quot;">​</a></h3><p>When using either the ssh:// or file:// transport, the GIT_PROTOCOL environment variable must be set explicitly to include &quot;version=2&quot;. The server may need to be configured to allow this environment variable to pass.</p><h3 id="http-transport" tabindex="-1">HTTP Transport <a class="header-anchor" href="#http-transport" aria-label="Permalink to &quot;HTTP Transport&quot;">​</a></h3><p>When using the http:// or https:// transport a client makes a &quot;smart&quot; info/refs request as described in <strong>gitprotocol-http</strong>(5) and requests that v2 be used by supplying &quot;version=2&quot; in the <strong>Git-Protocol</strong> header.</p><blockquote><pre><code>C: GET $GIT_URL/info/refs?service=git-upload-pack HTTP/1.0
C: Git-Protocol: version=2
</code></pre></blockquote><p>A v2 server would reply:</p><blockquote><pre><code>S: 200 OK
S: &lt;Some headers&gt;
S: ...
S:
S: 000eversion 2\\n
S: &lt;capability-advertisement&gt;
</code></pre></blockquote><p>Subsequent requests are then made directly to the service <strong>$GIT_URL/git-upload-pack</strong>. (This works the same for git-receive-pack).</p><p>Uses the <strong>--http-backend-info-refs</strong> option to <strong>git-upload-pack</strong>(1).</p><p>The server may need to be configured to pass this header&#39;s contents via the <strong>GIT_PROTOCOL</strong> variable. See the discussion in <strong>git-http-backend.txt</strong>.</p><h2 id="capability-advertisement" tabindex="-1">CAPABILITY ADVERTISEMENT <a class="header-anchor" href="#capability-advertisement" aria-label="Permalink to &quot;CAPABILITY ADVERTISEMENT&quot;">​</a></h2><p>A server which decides to communicate (based on a request from a client) using protocol version 2, notifies the client by sending a version string in its initial response followed by an advertisement of its capabilities. Each capability is a key with an optional value. Clients must ignore all unknown keys. Semantics of unknown values are left to the definition of each key. Some capabilities will describe commands which can be requested to be executed by the client.</p><blockquote><pre><code>capability-advertisement = protocol-version
      capability-list
      flush-pkt
</code></pre></blockquote><blockquote><pre><code>protocol-version = PKT-LINE(&quot;version 2&quot; LF)
capability-list = *capability
capability = PKT-LINE(key[=value] LF)
</code></pre></blockquote><blockquote><pre><code>key = 1*(ALPHA | DIGIT | &quot;-_&quot;)
value = 1*(ALPHA | DIGIT | &quot; -_.,?\\/{}[]()&lt;&gt;!@#$%^&amp;*+=:;&quot;)
</code></pre></blockquote><h2 id="command-request" tabindex="-1">COMMAND REQUEST <a class="header-anchor" href="#command-request" aria-label="Permalink to &quot;COMMAND REQUEST&quot;">​</a></h2><p>After receiving the capability advertisement, a client can then issue a request to select the command it wants with any particular capabilities or arguments. There is then an optional section where the client can provide any command specific parameters or queries. Only a single command can be requested at a time.</p><blockquote><pre><code>request = empty-request | command-request
empty-request = flush-pkt
command-request = command
    capability-list
    delim-pkt
    command-args
    flush-pkt
command = PKT-LINE(&quot;command=&quot; key LF)
command-args = *command-specific-arg
</code></pre></blockquote><blockquote><pre><code>command-specific-args are packet line framed arguments defined by
each individual command.
</code></pre></blockquote><p>The server will then check to ensure that the client&#39;s request is comprised of a valid command as well as valid capabilities which were advertised. If the request is valid the server will then execute the command. A server MUST wait till it has received the client&#39;s entire request before issuing a response. The format of the response is determined by the command being executed, but in all cases a flush-pkt indicates the end of the response.</p><p>When a command has finished, and the client has received the entire response from the server, a client can either request that another command be executed or can terminate the connection. A client may optionally send an empty request consisting of just a flush-pkt to indicate that no more requests will be made.</p><h2 id="capabilities" tabindex="-1">CAPABILITIES <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;CAPABILITIES&quot;">​</a></h2><p>There are two different types of capabilities: normal capabilities, which can be used to convey information or alter the behavior of a request, and commands, which are the core actions that a client wants to perform (fetch, push, etc).</p><p>Protocol version 2 is stateless by default. This means that all commands must only last a single round and be stateless from the perspective of the server side, unless the client has requested a capability indicating that state should be maintained by the server. Clients MUST NOT require state management on the server side in order to function correctly. This permits simple round-robin load-balancing on the server side, without needing to worry about state management.</p><h3 id="agent" tabindex="-1">agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;agent&quot;">​</a></h3><p>The server can advertise the <strong>agent</strong> capability with a value <strong>X</strong> (in the form <strong>agent=X</strong>) to notify the client that the server is running version <strong>X</strong>. The client may optionally send its own agent string by including the <strong>agent</strong> capability with a value <strong>Y</strong> (in the form <strong>agent=Y</strong>) in its request to the server (but it MUST NOT do so if the server did not advertise the agent capability). The <strong>X</strong> and <strong>Y</strong> strings may contain any printable ASCII characters except space (i.e., the byte range 32 &lt; x &lt; 127), and are typically of the form &quot;package/version&quot; (e.g., &quot;git/1.8.3.1&quot;). The agent strings are purely informative for statistics and debugging purposes, and MUST NOT be used to programmatically assume the presence or absence of particular features.</p><h3 id="ls-refs" tabindex="-1">ls-refs <a class="header-anchor" href="#ls-refs" aria-label="Permalink to &quot;ls-refs&quot;">​</a></h3><p><strong>ls-refs</strong> is the command used to request a reference advertisement in v2. Unlike the current reference advertisement, ls-refs takes in arguments which can be used to limit the refs sent from the server.</p><p>Additional features not supported in the base command will be advertised as the value of the command in the capability advertisement in the form of a space separated list of features: &quot;&lt;command&gt;=&lt;feature 1&gt; &lt;feature 2&gt;&quot;</p><p>ls-refs takes in the following arguments:</p><blockquote><pre><code>   symrefs
In addition to the object pointed by it, show the underlying ref
pointed by it when showing a symbolic ref.
   peel
Show peeled tags.
   ref-prefix &lt;prefix&gt;
When specified, only references having a prefix matching one of
the provided prefixes are displayed. Multiple instances may be
given, in which case references matching any prefix will be
shown. Note that this is purely for optimization; a server MAY
show refs not matching the prefix if it chooses, and clients
should filter the result themselves.
</code></pre></blockquote><p>If the <em>unborn</em> feature is advertised the following argument can be included in the client&#39;s request.</p><blockquote><pre><code>   unborn
The server will send information about HEAD even if it is a symref
pointing to an unborn branch in the form &quot;unborn HEAD
symref-target:&lt;target&gt;&quot;.
</code></pre></blockquote><p>The output of ls-refs is as follows:</p><blockquote><pre><code>output = *ref
  flush-pkt
obj-id-or-unborn = (obj-id | &quot;unborn&quot;)
ref = PKT-LINE(obj-id-or-unborn SP refname *(SP ref-attribute) LF)
ref-attribute = (symref | peeled)
symref = &quot;symref-target:&quot; symref-target
peeled = &quot;peeled:&quot; obj-id
</code></pre></blockquote><h3 id="fetch" tabindex="-1">fetch <a class="header-anchor" href="#fetch" aria-label="Permalink to &quot;fetch&quot;">​</a></h3><p><strong>fetch</strong> is the command used to fetch a packfile in v2. It can be looked at as a modified version of the v1 fetch where the ref-advertisement is stripped out (since the <strong>ls-refs</strong> command fills that role) and the message format is tweaked to eliminate redundancies and permit easy addition of future extensions.</p><p>Additional features not supported in the base command will be advertised as the value of the command in the capability advertisement in the form of a space separated list of features: &quot;&lt;command&gt;=&lt;feature 1&gt; &lt;feature 2&gt;&quot;</p><p>A <strong>fetch</strong> request can take the following arguments:</p><blockquote><pre><code>   want &lt;oid&gt;
Indicates to the server an object which the client wants to
retrieve.  Wants can be anything and are not limited to
advertised objects.
</code></pre></blockquote><blockquote><pre><code>   have &lt;oid&gt;
Indicates to the server an object which the client has locally.
This allows the server to make a packfile which only contains
the objects that the client needs. Multiple &#39;have&#39; lines can be
supplied.
</code></pre></blockquote><blockquote><pre><code>   done
Indicates to the server that negotiation should terminate (or
not even begin if performing a clone) and that the server should
use the information supplied in the request to construct the
packfile.
</code></pre></blockquote><blockquote><pre><code>   thin-pack
Request that a thin pack be sent, which is a pack with deltas
which reference base objects not contained within the pack (but
are known to exist at the receiving end). This can reduce the
network traffic significantly, but it requires the receiving end
to know how to &quot;thicken&quot; these packs by adding the missing bases
to the pack.
</code></pre></blockquote><blockquote><pre><code>   no-progress
Request that progress information that would normally be sent on
side-band channel 2, during the packfile transfer, should not be
sent.  However, the side-band channel 3 is still used for error
responses.
</code></pre></blockquote><blockquote><pre><code>   include-tag
Request that annotated tags should be sent if the objects they
point to are being sent.
</code></pre></blockquote><blockquote><pre><code>   ofs-delta
Indicate that the client understands PACKv2 with delta referring
to its base by position in pack rather than by an oid.  That is,
they can read OBJ_OFS_DELTA (aka type 6) in a packfile.
</code></pre></blockquote><p>If the <em>shallow</em> feature is advertised the following arguments can be included in the clients request as well as the potential addition of the <em>shallow-info</em> section in the server&#39;s response as explained below.</p><blockquote><pre><code>   shallow &lt;oid&gt;
A client must notify the server of all commits for which it only
has shallow copies (meaning that it doesn&#39;t have the parents of
a commit) by supplying a &#39;shallow &lt;oid&gt;&#39; line for each such
object so that the server is aware of the limitations of the
client&#39;s history.  This is so that the server is aware that the
client may not have all objects reachable from such commits.
</code></pre></blockquote><blockquote><pre><code>   deepen &lt;depth&gt;
Requests that the fetch/clone should be shallow having a commit
depth of &lt;depth&gt; relative to the remote side.
</code></pre></blockquote><blockquote><pre><code>   deepen-relative
Requests that the semantics of the &quot;deepen&quot; command be changed
to indicate that the depth requested is relative to the client&#39;s
current shallow boundary, instead of relative to the requested
commits.
</code></pre></blockquote><blockquote><pre><code>   deepen-since &lt;timestamp&gt;
Requests that the shallow clone/fetch should be cut at a
specific time, instead of depth.  Internally it&#39;s equivalent to
doing &quot;git rev-list --max-age=&lt;timestamp&gt;&quot;. Cannot be used with
&quot;deepen&quot;.
</code></pre></blockquote><blockquote><pre><code>   deepen-not &lt;rev&gt;
Requests that the shallow clone/fetch should be cut at a
specific revision specified by &#39;&lt;rev&gt;&#39;, instead of a depth.
Internally it&#39;s equivalent of doing &quot;git rev-list --not &lt;rev&gt;&quot;.
Cannot be used with &quot;deepen&quot;, but can be used with
&quot;deepen-since&quot;.
</code></pre></blockquote><p>If the <em>filter</em> feature is advertised, the following argument can be included in the client&#39;s request:</p><blockquote><pre><code>   filter &lt;filter-spec&gt;
Request that various objects from the packfile be omitted
using one of several filtering techniques. These are intended
for use with partial clone and partial fetch operations. See
\`rev-list\` for possible &quot;filter-spec&quot; values. When communicating
with other processes, senders SHOULD translate scaled integers
(e.g. &quot;1k&quot;) into a fully-expanded form (e.g. &quot;1024&quot;) to aid
interoperability with older receivers that may not understand
newly-invented scaling suffixes. However, receivers SHOULD
accept the following suffixes: &#39;k&#39;, &#39;m&#39;, and &#39;g&#39; for 1024,
1048576, and 1073741824, respectively.
</code></pre></blockquote><p>If the <em>ref-in-want</em> feature is advertised, the following argument can be included in the client&#39;s request as well as the potential addition of the <em>wanted-refs</em> section in the server&#39;s response as explained below.</p><blockquote><pre><code>   want-ref &lt;ref&gt;
Indicates to the server that the client wants to retrieve a
particular ref, where &lt;ref&gt; is the full name of a ref on the
server.
</code></pre></blockquote><p>If the <em>sideband-all</em> feature is advertised, the following argument can be included in the client&#39;s request:</p><blockquote><pre><code>   sideband-all
Instruct the server to send the whole response multiplexed, not just
the packfile section. All non-flush and non-delim PKT-LINE in the
response (not only in the packfile section) will then start with a byte
indicating its sideband (1, 2, or 3), and the server may send &quot;0005\\2&quot;
(a PKT-LINE of sideband 2 with no payload) as a keepalive packet.
</code></pre></blockquote><p>If the <em>packfile-uris</em> feature is advertised, the following argument can be included in the client&#39;s request as well as the potential addition of the <em>packfile-uris</em> section in the server&#39;s response as explained below.</p><blockquote><pre><code>   packfile-uris &lt;comma-separated list of protocols&gt;
Indicates to the server that the client is willing to receive
URIs of any of the given protocols in place of objects in the
sent packfile. Before performing the connectivity check, the
client should download from all given URIs. Currently, the
protocols supported are &quot;http&quot; and &quot;https&quot;.
</code></pre></blockquote><p>If the <em>wait-for-done</em> feature is advertised, the following argument can be included in the client&#39;s request.</p><blockquote><pre><code>   wait-for-done
Indicates to the server that it should never send &quot;ready&quot;, but
should wait for the client to say &quot;done&quot; before sending the
packfile.
</code></pre></blockquote><p>The response of <strong>fetch</strong> is broken into a number of sections separated by delimiter packets (0001), with each section beginning with its section header. Most sections are sent only when the packfile is sent.</p><blockquote><pre><code>output = acknowledgements flush-pkt |
  [acknowledgments delim-pkt] [shallow-info delim-pkt]
  [wanted-refs delim-pkt] [packfile-uris delim-pkt]
  packfile flush-pkt
</code></pre></blockquote><blockquote><pre><code>acknowledgments = PKT-LINE(&quot;acknowledgments&quot; LF)
    (nak | *ack)
    (ready)
ready = PKT-LINE(&quot;ready&quot; LF)
nak = PKT-LINE(&quot;NAK&quot; LF)
ack = PKT-LINE(&quot;ACK&quot; SP obj-id LF)
</code></pre></blockquote><blockquote><pre><code>shallow-info = PKT-LINE(&quot;shallow-info&quot; LF)
 *PKT-LINE((shallow | unshallow) LF)
shallow = &quot;shallow&quot; SP obj-id
unshallow = &quot;unshallow&quot; SP obj-id
</code></pre></blockquote><blockquote><pre><code>wanted-refs = PKT-LINE(&quot;wanted-refs&quot; LF)
*PKT-LINE(wanted-ref LF)
wanted-ref = obj-id SP refname
</code></pre></blockquote><blockquote><pre><code>packfile-uris = PKT-LINE(&quot;packfile-uris&quot; LF) *packfile-uri
packfile-uri = PKT-LINE(40*(HEXDIGIT) SP *%x20-ff LF)
</code></pre></blockquote><blockquote><pre><code>packfile = PKT-LINE(&quot;packfile&quot; LF)
    *PKT-LINE(%x01-03 *%x00-ff)
</code></pre></blockquote><blockquote><pre><code>   acknowledgments section
* If the client determines that it is finished with negotiations by
  sending a &quot;done&quot; line (thus requiring the server to send a packfile),
  the acknowledgments sections MUST be omitted from the server&#39;s
  response.
</code></pre></blockquote><blockquote><p>·</p><p>Always begins with the section header &quot;acknowledgments&quot;</p></blockquote><blockquote><p>·</p><p>The server will respond with &quot;NAK&quot; if none of the object ids sent as have lines were common.</p></blockquote><blockquote><p>·</p><p>The server will respond with &quot;ACK obj-id&quot; for all of the object ids sent as have lines which are common.</p></blockquote><blockquote><p>·</p><p>A response cannot have both &quot;ACK&quot; lines as well as a &quot;NAK&quot; line.</p></blockquote><blockquote><p>·</p><p>The server will respond with a &quot;ready&quot; line indicating that the server has found an acceptable common base and is ready to make and send a packfile (which will be found in the packfile section of the same response)</p></blockquote><blockquote><p>·</p><p>If the server has found a suitable cut point and has decided to send a &quot;ready&quot; line, then the server can decide to (as an optimization) omit any &quot;ACK&quot; lines it would have sent during its response. This is because the server will have already determined the objects it plans to send to the client and no further negotiation is needed.</p><blockquote><pre><code>   shallow-info section
* If the client has requested a shallow fetch/clone, a shallow
  client requests a fetch or the server is shallow then the
  server&#39;s response may include a shallow-info section.  The
  shallow-info section will be included if (due to one of the
  above conditions) the server needs to inform the client of any
  shallow boundaries or adjustments to the clients already
  existing shallow boundaries.
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Always begins with the section header &quot;shallow-info&quot;</p></blockquote><blockquote><p>·</p><p>If a positive depth is requested, the server will compute the set of commits which are no deeper than the desired depth.</p></blockquote><blockquote><p>·</p><p>The server sends a &quot;shallow obj-id&quot; line for each commit whose parents will not be sent in the following packfile.</p></blockquote><blockquote><p>·</p><p>The server sends an &quot;unshallow obj-id&quot; line for each commit which the client has indicated is shallow, but is no longer shallow as a result of the fetch (due to its parents being sent in the following packfile).</p></blockquote><blockquote><p>·</p><p>The server MUST NOT send any &quot;unshallow&quot; lines for anything which the client has not indicated was shallow as a part of its request.</p><blockquote><pre><code>   wanted-refs section
* This section is only included if the client has requested a
  ref using a &#39;want-ref&#39; line and if a packfile section is also
  included in the response.
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Always begins with the section header &quot;wanted-refs&quot;.</p></blockquote><blockquote><p>·</p><p>The server will send a ref listing (&quot;&lt;oid&gt; &lt;refname&gt;&quot;) for each reference requested using <em>want-ref</em> lines.</p></blockquote><blockquote><p>·</p><p>The server MUST NOT send any refs which were not requested using <em>want-ref</em> lines.</p><blockquote><pre><code>   packfile-uris section
* This section is only included if the client sent
  &#39;packfile-uris&#39; and the server has at least one such URI to
  send.
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Always begins with the section header &quot;packfile-uris&quot;.</p></blockquote><blockquote><p>·</p><p>For each URI the server sends, it sends a hash of the pack&#39;s contents (as output by git index-pack) followed by the URI.</p></blockquote><blockquote><p>·</p><p>The hashes are 40 hex characters long. When Git upgrades to a new hash algorithm, this might need to be updated. (It should match whatever index-pack outputs after &quot;pack\\t&quot; or &quot;keep\\t&quot;.</p><blockquote><pre><code>   packfile section
* This section is only included if the client has sent &#39;want&#39;
  lines in its request and either requested that no more
  negotiation be done by sending &#39;done&#39; or if the server has
  decided it has found a sufficient cut point to produce a
  packfile.
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Always begins with the section header &quot;packfile&quot;</p></blockquote><blockquote><p>·</p><p>The transmission of the packfile begins immediately after the section header</p></blockquote><blockquote><p>·</p><p>The data transfer of the packfile is always multiplexed, using the same semantics of the <em>side-band-64k</em> capability from protocol version 1. This means that each packet, during the packfile data stream, is made up of a leading 4-byte pkt-line length (typical of the pkt-line format), followed by a 1-byte stream code, followed by the actual data.</p><blockquote><pre><code> The stream code can be one of:
1 - pack data
2 - progress messages
3 - fatal error message just before stream aborts
</code></pre></blockquote></blockquote><h3 id="server-option" tabindex="-1">server-option <a class="header-anchor" href="#server-option" aria-label="Permalink to &quot;server-option&quot;">​</a></h3><p>If advertised, indicates that any number of server specific options can be included in a request. This is done by sending each option as a &quot;server-option=&lt;option&gt;&quot; capability line in the capability-list section of a request.</p><p>The provided options must not contain a NUL or LF character.</p><h3 id="object-format" tabindex="-1">object-format <a class="header-anchor" href="#object-format" aria-label="Permalink to &quot;object-format&quot;">​</a></h3><p>The server can advertise the <strong>object-format</strong> capability with a value <strong>X</strong> (in the form <strong>object-format=X</strong>) to notify the client that the server is able to deal with objects using hash algorithm X. If not specified, the server is assumed to only handle SHA-1. If the client would like to use a hash algorithm other than SHA-1, it should specify its object-format string.</p><h3 id="session-id-session-id" tabindex="-1">session-id=&lt;session id&gt; <a class="header-anchor" href="#session-id-session-id" aria-label="Permalink to &quot;session-id=\\&lt;session id\\&gt;&quot;">​</a></h3><p>The server may advertise a session ID that can be used to identify this process across multiple requests. The client may advertise its own session ID back to the server as well.</p><p>Session IDs should be unique to a given process. They must fit within a packet-line, and must not contain non-printable or whitespace characters. The current implementation uses trace2 session IDs (see <strong>api-trace2</strong>[1] for details), but this may change and users of the session ID should not rely on this fact.</p><h3 id="object-info" tabindex="-1">object-info <a class="header-anchor" href="#object-info" aria-label="Permalink to &quot;object-info&quot;">​</a></h3><p><strong>object-info</strong> is the command to retrieve information about one or more objects. Its main purpose is to allow a client to make decisions based on this information without having to fully fetch objects. Object size is the only information that is currently supported.</p><p>An <strong>object-info</strong> request takes the following arguments:</p><blockquote><pre><code>size
Requests size information to be returned for each listed object id.
</code></pre></blockquote><blockquote><pre><code>oid &lt;oid&gt;
Indicates to the server an object which the client wants to obtain
information for.
</code></pre></blockquote><p>The response of <strong>object-info</strong> is a list of the requested object ids and associated requested information, each separated by a single space.</p><blockquote><pre><code>output = info flush-pkt
</code></pre></blockquote><blockquote><pre><code>info = PKT-LINE(attrs) LF)
	*PKT-LINE(obj-info LF)
</code></pre></blockquote><blockquote><pre><code>attrs = attr | attrs SP attrs
</code></pre></blockquote><blockquote><pre><code>attr = &quot;size&quot;
</code></pre></blockquote><blockquote><pre><code>obj-info = obj-id SP obj-size
</code></pre></blockquote><h3 id="bundle-uri" tabindex="-1">bundle-uri <a class="header-anchor" href="#bundle-uri" aria-label="Permalink to &quot;bundle-uri&quot;">​</a></h3><p>If the <em>bundle-uri</em> capability is advertised, the server supports the &quot;bundle-uri&quot; command.</p><p>The capability is currently advertised with no value (i.e. not &quot;bundle-uri=somevalue&quot;), a value may be added in the future for supporting command-wide extensions. Clients MUST ignore any unknown capability values and proceed with the &#39;bundle-uri\` dialog they support.</p><p>The <em>bundle-uri</em> command is intended to be issued before <strong>fetch</strong> to get URIs to bundle files (see <strong>git-bundle</strong>(1)) to &quot;seed&quot; and inform the subsequent <strong>fetch</strong> command.</p><p>The client CAN issue <strong>bundle-uri</strong> before or after any other valid command. To be useful to clients it&#39;s expected that it&#39;ll be issued after an <strong>ls-refs</strong> and before <strong>fetch</strong>, but CAN be issued at any time in the dialog.</p><br>`,139),h=e("<blockquote><p>The intent of the feature is optimize for server resource consumption in the common case by changing the common case of fetching a very large PACK during <strong>git-clone</strong>(1) into a smaller incremental fetch.</p><p>It also allows servers to achieve better caching in combination with an <strong>uploadpack.packObjectsHook</strong> (see <strong>git-config</strong>(1)).</p><p>By having new clones or fetches be a more predictable and common negotiation against the tips of recently produces *.bundle file(s). Servers might even pre-generate the results of such negotiations for the <strong>uploadpack.packObjectsHook</strong> as new pushes come in.</p><p>One way that servers could take advantage of these bundles is that the server would anticipate that fresh clones will download a known bundle, followed by catching up to the current state of the repository using ref tips found in that bundle (or bundles).</p></blockquote><br>",2),u=e("<blockquote><p>A <strong>bundle-uri</strong> request takes no arguments, and as noted above does not currently advertise a capability value. Both may be added in the future.</p><p>When the client issues a <strong>command=bundle-uri</strong> request, the response is a list of key-value pairs provided as packet lines with value <strong>&lt;key&gt;=&lt;value&gt;</strong>. Each <strong>&lt;key&gt;</strong> should be interpreted as a config key from the *<em>bundle.*</em> * namespace to construct a list of bundles. These keys are grouped by a <strong>bundle.&lt;id&gt;.</strong> subsection, where each key corresponding to a given <strong>&lt;id&gt;</strong> contributes attributes to the bundle defined by that <strong>&lt;id&gt;</strong>. See <strong>git-config</strong>(1) for the specific details of these keys and how the Git client will interpret their values.</p><p>Clients MUST parse the line according to the above format, lines that do not conform to the format SHOULD be discarded. The user MAY be warned in such a case.</p></blockquote><br>",2),p=e("<blockquote><p>URI CONTENTS</p><blockquote><p>The content at the advertised URIs MUST be one of two types.</p><p>The advertised URI may contain a bundle file that <strong>git bundle verify</strong> would accept. I.e. they MUST contain one or more reference tips for use by the client, MUST indicate prerequisites (in any) with standard &quot;-&quot; prefixes, and MUST indicate their &quot;object-format&quot;, if applicable.</p><p>The advertised URI may alternatively contain a plaintext file that <strong>git config --list</strong> would accept (with the <strong>--file</strong> option). The key-value pairs in this list are in the *<em>bundle.*</em> * namespace (see <strong>git-config</strong>(1)).</p></blockquote><p>bundle-uri CLIENT ERROR RECOVERY</p><blockquote><p>A client MUST above all gracefully degrade on errors, whether that error is because of bad missing/data in the bundle URI(s), because that client is too dumb to e.g. understand and fully parse out bundle headers and their prerequisite relationships, or something else.</p><p>Server operators should feel confident in turning on &quot;bundle-uri&quot; and not worry if e.g. their CDN goes down that clones or fetches will run into hard failures. Even if the server bundle(s) are incomplete, or bad in some way the client should still end up with a functioning repository, just as if it had chosen not to use this protocol extension.</p><p>All subsequent discussion on client and server interaction MUST keep this in mind.</p></blockquote><p>bundle-uri SERVER TO CLIENT</p><blockquote><p>The ordering of the returned bundle uris is not significant. Clients MUST parse their headers to discover their contained OIDS and prerequisites. A client MUST consider the content of the bundle(s) themselves and their header as the ultimate source of truth.</p><p>A server MAY even return bundle(s) that don&#39;t have any direct relationship to the repository being cloned (either through accident, or intentional &quot;clever&quot; configuration), and expect a client to sort out what data they&#39;d like from the bundle(s), if any.</p></blockquote><p>bundle-uri CLIENT TO SERVER</p><blockquote><p>The client SHOULD provide reference tips found in the bundle header(s) as <em>have</em> lines in any subsequent <strong>fetch</strong> request. A client MAY also ignore the bundle(s) entirely if doing so is deemed worse for some reason, e.g. if the bundles can&#39;t be downloaded, it doesn&#39;t like the tips it finds etc.</p></blockquote><p>WHEN ADVERTISED BUNDLE(S) REQUIRE NO FURTHER NEGOTIATION</p><blockquote><p>If after issuing <strong>bundle-uri</strong> and <strong>ls-refs</strong>, and getting the header(s) of the bundle(s) the client finds that the ref tips it wants can be retrieved entirely from advertised bundle(s), the client MAY disconnect from the Git server. The results of such a <em>clone</em> or <em>fetch</em> should be indistinguishable from the state attained without using bundle-uri.</p></blockquote><p>EARLY CLIENT DISCONNECTIONS AND ERROR RECOVERY</p><blockquote><p>A client MAY perform an early disconnect while still downloading the bundle(s) (having streamed and parsed their headers). In such a case the client MUST gracefully recover from any errors related to finishing the download and validation of the bundle(s).</p><p>I.e. a client might need to re-connect and issue a <em>fetch</em> command, and possibly fall back to not making use of <em>bundle-uri</em> at all.</p><p>This &quot;MAY&quot; behavior is specified as such (and not a &quot;SHOULD&quot;) on the assumption that a server advertising bundle uris is more likely than not to be serving up a relatively large repository, and to be pointing to URIs that have a good chance of being in working order. A client MAY e.g. look at the payload size of the bundles as a heuristic to see if an early disconnect is worth it, should falling back on a full &quot;fetch&quot; dialog be necessary.</p></blockquote><p>WHEN ADVERTISED BUNDLE(S) REQUIRE FURTHER NEGOTIATION</p><blockquote><p>A client SHOULD commence a negotiation of a PACK from the server via the &quot;fetch&quot; command using the OID tips found in advertised bundles, even if&#39;s still in the process of downloading those bundle(s).</p><p>This allows for aggressive early disconnects from any interactive server dialog. The client blindly trusts that the advertised OID tips are relevant, and issues them as <em>have</em> lines, it then requests any tips it would like (usually from the &quot;ls-refs&quot; advertisement) via <em>want</em> lines. The server will then compute a (hopefully small) PACK with the expected difference between the tips from the bundle(s) and the data requested.</p><p>The only connection the client then needs to keep active is to the concurrently downloading static bundle(s), when those and the incremental PACK are retrieved they should be inflated and validated. Any errors at this point should be gracefully recovered from, see above.</p></blockquote></blockquote><br>",2),b=e('<blockquote><p>The client constructs a bundle list from the <strong>&lt;key&gt;=&lt;value&gt;</strong> pairs provided by the server. These pairs are part of the *<em>bundle.*</em> * namespace as documented in <strong>git-config</strong>(1). In this section, we discuss some of these keys and describe the actions the client will do in response to this information.</p><p>In particular, the <strong>bundle.version</strong> key specifies an integer value. The only accepted value at the moment is <strong>1</strong>, but if the client sees an unexpected value here then the client MUST ignore the bundle list.</p><p>As long as <strong>bundle.version</strong> is understood, all other unknown keys MAY be ignored by the client. The server will guarantee compatibility with older clients, though newer clients may be better able to use the extra keys to minimize downloads.</p><p>Any backwards-incompatible addition of pre-URI key-value will be guarded by a new <strong>bundle.version</strong> value or values in <em>bundle-uri</em> capability advertisement itself, and/or by new future <strong>bundle-uri</strong> request arguments.</p><p>Some example key-value pairs that are not currently implemented but could be implemented in the future include:</p><blockquote><p>·</p><p>Add a &quot;hash=&lt;val&gt;&quot; or &quot;size=&lt;bytes&gt;&quot; advertise the expected hash or size of the bundle file.</p></blockquote><blockquote><p>·</p><p>Advertise that one or more bundle files are the same (to e.g. have clients round-robin or otherwise choose one of N possible files).</p></blockquote><blockquote><p>·</p><p>A &quot;oid=&lt;OID&gt;&quot; shortcut and &quot;prerequisite=&lt;OID&gt;&quot; shortcut. For expressing the common case of a bundle with one tip and no prerequisites, or one tip and one prerequisite.</p><p>This would allow for optimizing the common case of servers who&#39;d like to provide one &quot;big bundle&quot; containing only their &quot;main&quot; branch, and/or incremental updates thereof.</p><p>A client receiving such a a response MAY assume that they can skip retrieving the header from a bundle at the indicated URI, and thus save themselves and the server(s) the request(s) needed to inspect the headers of that bundle or bundles.</p></blockquote></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><ol><li></li></ol><p>: api-trace2</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file:///usr/share/doc/git/technical/api-trace2.html</span></span></code></pre></div>',7);function f(o,m,g,q,k,v){return i(),s("div",null,[a("h1",c,r(o.$params.man),1),d,t(" **DISCUSSION of bundle-uri** "),h,t(" **PROTOCOL for bundle-uri** "),u,t(" **bundle-uri CLIENT AND SERVER EXPECTATIONS** "),p,t(" **bundle-uri PROTOCOL FEATURES** "),b])}const T=n(l,[["render",f]]);export{y as __pageData,T as default};
